package com.example.starter.playout.clock;

import java.time.Instant;

/**
 * 可注入的合成时钟；测试与本地演示可显式设定时间，生产环境不接真实广电设备。
 */
public class SyntheticClock {

    private volatile Instant now = Instant.parse("2026-01-01T00:00:00Z");

    public Instant instant() {
        return now;
    }

    public void setInstant(Instant instant) {
        this.now = instant;
    }
}

package com.example.starter.playout.clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时钟装配；容器内唯一的合成时钟 Bean，供调度与接口默认取时使用。
 */
@Configuration
public class ClockConfig {

    @Bean
    public SyntheticClock syntheticClock() {
        return new SyntheticClock();
    }
}

package com.example.starter.playout.adapter;

/**
 * 播出适配器指令（发往虚构的下游播出设备）。
 *
 * @param channel      频道标识
 * @param asRunSequence 频道内单调递增的播出序号
 * @param content      指令内容描述（素材摘要或直播插播requestId）
 */
public record PlayoutCommand(String channel, long asRunSequence, String content) {
}

package com.example.starter.playout.adapter;

/**
 * 播出适配器抽象；实现只做本地合成动作，不连接真实广电设备。
 */
public interface PlayoutAdapter {

    /**
     * 通知适配器开始播出某序号对应的素材。
     */
    void start(PlayoutCommand command);
}

package com.example.starter.playout.adapter;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

/**
 * 合成播出适配器：仅记录日志，模拟向播出设备下发开始指令。
 */
@Component
public class LoggingPlayoutAdapter implements PlayoutAdapter {

    private static final Logger log = LoggerFactory.getLogger(LoggingPlayoutAdapter.class);

    @Override
    public void start(PlayoutCommand command) {
        // 骨架占位
    }
}

