/**
 * 把 (from, to] 的时间轴结算为 as-run 段；from 为 null 表示首次结算。
 * 同一频道任一时刻最多一个实际素材；插播结束后只恢复当前应播素材，不补播。
 */
private List<AsRunView> settle(String channel, Long versionId, Instant from, Instant to) {
    List<PlaylistItemRow> items = versionId == null
            ? List.of() : repo.findItemsByVersion(versionId);
    List<LiveInsertRow> lives = repo.findLivesOverlapping(channel,
            from == null ? Instant.MIN : from, to);

    Optional<AsRunRow> existingOpen = repo.findOpenAsRun(channel);
    long seq = repo.maxChannelSeq(channel).orElse(0L);
    Instant createdAt = clock.instant();
    List<AsRunView> generated = new ArrayList<>();
    List<AsRunRow> openHolder = new ArrayList<>();
    existingOpen.ifPresent(openHolder::add);

    Identity startIdentity = identityAt(from == null ? to : from, items, lives);
    if (from != null) {
        // 对账 tick 之前的开放段：插播抢占或新版本可能已改变 from 时刻的应播素材。
        if (!openHolder.isEmpty()) {
            AsRunRow open = openHolder.get(0);
            if (!Identity.matches(open, startIdentity)) {
                repo.closeAsRun(open.id(), from);
                openHolder.clear();
            }
        }
        if (openHolder.isEmpty() && !startIdentity.gap()) {
            seq = openNewSegment(channel, versionId, items, lives, from,
                    seq, createdAt, generated, openHolder);
        }
    }

    if (from != null) {
        TreeSet<Instant> cuts = new TreeSet<>();
        for (PlaylistItemRow item : items) {
            addCut(cuts, item.startTime(), from, to);
            addCut(cuts, item.endTime(), from, to);
        }
        for (LiveInsertRow live : lives) {
            addCut(cuts, live.startTime(), from, to);
            if (live.endTime() != null) {
                addCut(cuts, live.endTime(), from, to);
            }
        }
        Identity current = startIdentity;
        for (Instant cut : cuts) {
            Identity after = identityAt(cut, items, lives);
            if (!after.equals(current)) {
                if (!current.gap()) {
                    AsRunRow open = openHolder.get(0);
                    repo.closeAsRun(open.id(), cut);
                    openHolder.clear();
                }
                if (!after.gap()) {
                    seq = openNewSegment(channel, versionId, items, lives, cut,
                            seq, createdAt, generated, openHolder);
                }
                current = after;
            }
        }
    } else {
        // 首次 tick：to 时刻的应播素材作为开放段；to 之前的历史不补播。
        if (existingOpen.isEmpty() && !startIdentity.gap()) {
            seq = openNewSegment(channel, versionId, items, lives, to,
                    seq, createdAt, generated, openHolder);
        }
    }
    return generated;
}

private long openNewSegment(String channel, Long versionId, List<PlaylistItemRow> items,
                            List<LiveInsertRow> lives, Instant start, long seq,
                            Instant createdAt, List<AsRunView> generated,
                            List<AsRunRow> openHolder) {
    Identity identity = identityAt(start, items, lives);
    long nextSeq = seq + 1;
    if (identity.live() != null) {
        LiveInsertRow live = identity.live();
        repo.insertAsRun(channel, nextSeq, versionId, "LIVE", null, null,
                live.requestId(), live.priority(), start, createdAt);
        repo.updateFirstSequence(channel, live.requestId(), nextSeq);
    } else {
        PlaylistItemRow item = identity.item();
        repo.insertAsRun(channel, nextSeq, versionId, "ITEM", item.itemId(),
                item.materialDigest(), null, null, start, createdAt);
    }
    AsRunRow inserted = repo.findAsRunBySeq(channel, nextSeq).orElseThrow();
    openHolder.clear();
    openHolder.add(inserted);
    generated.add(toView(inserted));
    adapter.start(new PlayoutCommand(channel, nextSeq,
            identity.live() != null ? "LIVE:" + identity.live().requestId()
                    : "ITEM:" + identity.item().itemId()));
    return nextSeq;
}

private static void addCut(TreeSet<Instant> cuts, Instant candidate, Instant from, Instant to) {
    if (candidate.isAfter(from) && !candidate.isAfter(to)) {
        cuts.add(candidate);
    }
}

